import heapq

def k_closest(points, k):
    heap = []
    for i, (x, y) in enumerate(points):
        dist = x*x + y*y
        if len(heap) < k:
            heapq.heappush(heap, (-dist, i))
        elif dist < -heap[0][0]:
            heapq.heappushpop(heap, (-dist, i))
    return [points[p[1]] for p in heap]
